mapper.select:
SELECT id, code, name, hosting_mode, status, base_url_host_policy, version, created_at, updated_at
FROM provider
WHERE id = #{id}

mapper.update:
UPDATE provider
SET name = #{name}, status = #{status}, base_url_host_policy = #{policy}, version=version+1, updated_at =
#{now}
WHERE id = #{id} AND version = #{expectedVersion}

UPDATE logical_model
SET display_name = #{displayName}, status = #{status}, version=version+1, updated_at = #{now}
WHERE id = #{id} AND version = #{expectedVersion}

UPDATE model_deployment
SET adapter_compatibility_json=JSON_SET(adapter_compatibility_json, '$.deploymentId', id)
WHERE id = #{id}

UPDATE model_deployment
SET status = #{status}, routing_priority = #{routingPriority}, routing_weight = #{routingWeight},
max_concurrent = #{maxConcurrent}, version=version+1, updated_at = #{now}
WHERE id = #{id} AND version = #{expectedVersion}

mapper.select:
SELECT id, code, name, hosting_mode, status, base_url_host_policy, version, created_at, updated_at
FROM provider


    AND status = #{status}

    AND hosting_mode = #{hostingMode}

ORDER BY id
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM provider


    AND status = #{status}

    AND hosting_mode = #{hostingMode}

SELECT id, model_code, display_name, model_family, immutable_model_revision, capability_profile_json,
status, active_points_price_version_id, active_routing_revision_id, version, created_at, updated_at
FROM logical_model


    AND status = #{status}

ORDER BY id
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM logical_model


    AND status = #{status}

SELECT id, logical_model_id, provider_id, deployment_code, endpoint_uri, remote_model_name, hosting_mode,
region_code, capability_revision, adapter_compatibility_json, adapter_evidence_ref, cost_model, status,
routing_priority, routing_weight, max_concurrent, capacity_pool_id, active_purchase_price_version_id,
active_credential_id, version, created_at, updated_at
FROM model_deployment


    AND status = #{status}
    AND logical_model_id = #{modelId}

ORDER BY id
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM model_deployment


    AND status = #{status}
    AND logical_model_id = #{modelId}

mapper.update:
UPDATE logical_model
SET active_points_price_version_id = #{priceId}, version=version+1, updated_at = #{now}
WHERE id = #{ownerId} AND version = #{expectedVersion}

UPDATE model_deployment
SET active_purchase_price_version_id = #{priceId}, version=version+1, updated_at = #{now}
WHERE id = #{ownerId} AND version = #{expectedVersion}

UPDATE model_deployment
SET active_credential_id = #{credentialId}, version=version+1, updated_at = #{now}
WHERE id = #{deploymentId}

UPDATE provider_credential
SET status='REVOKED', revoked_at = #{now}
WHERE id = #{id} AND status='ACTIVE'

UPDATE model_deployment
SET active_credential_id=NULL, status='DISABLED', version=version+1, updated_at = #{now}
WHERE id = #{deploymentId} AND active_credential_id = #{id}

mapper.select:
SELECT COUNT(*)
FROM provider_credential
WHERE deployment_id = #{deploymentId}

SELECT agent_id, logical_model_id AS model_id, status, version, granted_at, revoked_at
FROM agent_model_permission
WHERE agent_id = #{agentId} AND logical_model_id = #{modelId}

mapper.update:
UPDATE agent_model_permission
SET status='REVOKED', version=version+1, revoked_by = #{actorId}, revoked_at = #{now}, updated_at = #{now}
WHERE agent_id = #{agentId} AND logical_model_id = #{modelId} AND status='GRANTED'

